Официальный шаблон Vercel для мультидоменности на Next.js 16 использует именно proxy.ts:
```ts
export async function proxy(request: NextRequest) {
  const hostname = request.headers.get('host') || '';
  const { pathname } = request.nextUrl;
  if (pathname.startsWith('/domains')) return NextResponse.next();
  if (pathname === '/') return NextResponse.rewrite(new URL(`/domains/${hostname}`, request.url));
  return NextResponse.next();
}
export const config = { matcher: ['/((?!api|_next/static|_next/image|favicon.ico).*)'] };
```
То есть подход `/_sites/<brand>` реализуется как rewrite на сегмент `/domains/[domain]` (или `/tenant/[id]`, `/sites/[slug]`).

Второй канонический паттерн: резолвим tenantId по hostname и переписываем путь целиком, сохраняя контекст в заголовке:
```ts
const hostname = request.headers.get('host') || '';
const tenantId = await resolveTenantId(hostname);
const requestHeaders = new Headers(request.headers);
requestHeaders.set('x-tenant-id', tenantId);
if (pathname === '/') { url.pathname = `/tenant/${tenantId}`; return NextResponse.rewrite(url, { request: { headers: requestHeaders } }); }
if (pathname.startsWith('/blog')) { url.pathname = `/tenant/${tenantId}/blog${pathname.replace('/blog','')}`; return NextResponse.rewrite(url, { request: { headers: requestHeaders } }); }
```
